namespace ModernLibs.FileHelpers.Generator.Models;

/// <summary>
/// Equatable pipeline model representing a single annotated record type.
/// Contains ONLY primitives and EquatableArray — no ISymbol, SyntaxNode, or Compilation references.
/// This is a C# record: structural equality is auto-generated by the compiler.
/// </summary>
internal sealed record RecordModel(
    string Namespace,
    string TypeName,
    string TypeKind,
    bool IsReadOnly,
    string RecordKind,
    string Delimiter,
    EquatableArray<FieldModel> Fields,
    string? FixedMode = null,
    int IgnoreFirst = 0,
    int IgnoreLast = 0,
    bool IgnoreEmptyLines = false,
    char CommentMarker = '\0',
    int Condition = 0,
    string ConditionPattern = "",
    int MultilineMode = 3,
    int QuoteUnescapeMode = 0,
    int TrimMode = 0,
    bool HasHeader = false,
    bool IsRefStruct = false,
    bool ImplementsNotifyRead = false)
    ;
